    var probeCalls = 0;
    final hooks2 = _Hooks();
    final ok2 = await StructuredCompactor(
      session: session, state: state2, window: 8000, settings: _settings,
      judge: (ledger, [token]) { probeCalls++; return Future<String?>.value('["13"]'); },
